{
  "name": "pengunjung",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node src/server.js"
  },
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "express": "^5.1.0",
    "pg": "^8.16.0"
  }
}

import express from "express";
import pg from "pg";

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
// Tanpa ini, koneksi idle yang diputus database (misalnya saat db dimatikan) membuat aplikasi crash
pool.on("error", (err) => console.error("Koneksi database terputus:", err.message));
const version = process.env.APP_VERSION ?? "dev";
const app = express();

await pool.query(
  "CREATE TABLE IF NOT EXISTS kunjungan (id serial PRIMARY KEY, waktu timestamptz NOT NULL DEFAULT now())"
);

app.get("/", async (req, res) => {
  await pool.query("INSERT INTO kunjungan DEFAULT VALUES");
  const { rows } = await pool.query("SELECT count(*)::int AS n FROM kunjungan");
  res.type("text").send(`Halo dari server! Versi ${version}. Halaman ini sudah dibuka ${rows[0].n} kali.\n`);
});

app.get("/health", async (req, res) => {
  try {
    await pool.query("SELECT 1");
    res.json({ status: "ok", version });
  } catch {
    res.status(503).json({ status: "db-tidak-terjangkau", version });
  }
});

const port = Number(process.env.PORT ?? 3000);
const server = app.listen(port, () => console.log(`Server jalan di port ${port}, versi ${version}`));

for (const signal of ["SIGTERM", "SIGINT"]) {
  process.on(signal, () => {
    console.log(`${signal} diterima, menutup server dengan rapi...`);
    server.close(() => pool.end().then(() => process.exit(0)));
  });
}

{$DOMAIN} {
	encode zstd gzip
	reverse_proxy app:3000
}
